-- Move a character one square at a time, stopping at walls and waiting until each step is
-- finished.
-- grid-movement: original MIT-licensed native educational port.
-- Generated by tools/ports/generate.py; edit the specification to preserve parity.
-- Input: [width,height,step_seconds,repeat_delay,repeat_interval,buffer_seconds,dt,direction,...9_
-- state_values,...row_major_grid]
-- Output: [...9_next_state_values,visual_x,visual_y,steps_started,tiles_arrived,blocked_flag]
-- Persistent one-update controller. Directions 0=release,1=up,2=right,3=down,4=left (Y down).
-- State: tile_x,tile_y,target_x,target_y,progress,buffered_direction,held_direction,repeat_remaini
-- ng,buffer_remaining. Keep the first nine outputs for the next call. Zero tiles are walkable. dt
-- is 0..1 seconds; repeat delay/interval >=0.01 seconds. See README for event ordering and static-
-- map assumptions; [-1] means invalid configuration/state.
-- Precondition: finite, correctly shaped data; integer indices/counts/IDs.
-- See ../PORTS.md for examples, limits, and the shared test fixtures.

-- Count how many numbers are in this list.
local function port_length(a) return #a end
-- Read one number at a zero-based position; stop if that position does not exist.
local function port_get(a,i) assert(i>=0 and i==math.floor(i) and i<#a,"index"); return a[i+1] end
-- Choose the smaller of two numbers.
local function port_minimum(a,b) return math.min(a,b) end
-- Choose the larger of two numbers.
local function port_maximum(a,b) return math.max(a,b) end
-- Round down to a whole number; minus 0.1 becomes minus 1.
local function port_floor_num(a) return math.floor(a) end
-- Remove a negative sign so a distance or size is not negative.
local function port_abs_num(a) return math.abs(a) end

-- 1. Read one direction: up, right, down, left, or no button.
-- 2. Check the next square. Stay put if it is outside the map or contains a wall.
-- 3. Either jump straight to that square or slide to it over the chosen step time.
-- 4. Remember the newest direction briefly if it is pressed during a step. Try it after landing.
-- 5. Holding a direction waits for a short delay, then requests more steps at regular times.
-- Releasing stops those repeats.
local function compute(data)
    local w = 0
    local h = 0
    local step_seconds = 0
    local repeat_delay = 0
    local repeat_interval = 0
    local buffer_seconds = 0
    local remaining = 0
    local direction = 0
    local tile_x = 0
    local tile_y = 0
    local target_x = 0
    local target_y = 0
    local progress = 0
    local buffered = 0
    local held = 0
    local repeat_remaining = 0
    local buffer_remaining = 0
    local started = 0
    local arrived = 0
    local blocked = 0
    local visual_x = 0
    local visual_y = 0
    local advance = 0
    local nx = 0
    local ny = 0
    local passable = 0
    if (port_length(data) < 18) then
        return {-(1)}
    end
    w = port_get(data, 0)
    h = port_get(data, 1)
    step_seconds = port_get(data, 2)
    repeat_delay = port_get(data, 3)
    repeat_interval = port_get(data, 4)
    buffer_seconds = port_get(data, 5)
    remaining = port_get(data, 6)
    direction = port_get(data, 7)
    tile_x = port_get(data, 8)
    tile_y = port_get(data, 9)
    target_x = port_get(data, 10)
    target_y = port_get(data, 11)
    progress = port_get(data, 12)
    buffered = port_get(data, 13)
    held = port_get(data, 14)
    repeat_remaining = port_get(data, 15)
    buffer_remaining = port_get(data, 16)
    if ((w < 1) or (h < 1) or (port_floor_num(w) ~= w) or (port_floor_num(h) ~= h) or (port_length(data) ~= (17 + (w * h)))) then
        return {-(1)}
    end
    if ((step_seconds < 0) or (repeat_delay < 0.01) or (repeat_interval < 0.01) or (buffer_seconds < 0) or (remaining < 0) or (remaining > 1)) then
        return {-(1)}
    end
    if ((direction < 0) or (direction > 4) or (port_floor_num(direction) ~= direction) or (held < 0) or (held > 4) or (port_floor_num(held) ~= held) or (buffered < 0) or (buffered > 4) or (port_floor_num(buffered) ~= buffered)) then
        return {-(1)}
    end
    if ((tile_x < 0) or (tile_x >= w) or (tile_y < 0) or (tile_y >= h) or (target_x < 0) or (target_x >= w) or (target_y < 0) or (target_y >= h)) then
        return {-(1)}
    end
    if ((port_floor_num(tile_x) ~= tile_x) or (port_floor_num(tile_y) ~= tile_y) or (port_floor_num(target_x) ~= target_x) or (port_floor_num(target_y) ~= target_y)) then
        return {-(1)}
    end
    if ((progress < 0) or (progress > 1) or (repeat_remaining < 0) or (buffer_remaining < 0) or ((port_abs_num((target_x - tile_x)) + port_abs_num((target_y - tile_y))) > 1)) then
        return {-(1)}
    end
    if (((target_x == tile_x) and (target_y == tile_y) and (progress ~= 0)) or (port_get(data, ((17 + (tile_y * w)) + tile_x)) ~= 0) or (port_get(data, ((17 + (target_y * w)) + target_x)) ~= 0)) then
        return {-(1)}
    end
    -- Instant mode cannot resume a previously unfinished smooth step.
    if ((step_seconds == 0) and ((target_x ~= tile_x) or (target_y ~= tile_y))) then
        return {-(1)}
    end
    -- A changed direction is a fresh press; a release stops repeating but keeps a live buffer.
    if (direction ~= held) then
        held = direction
        repeat_remaining = 0
        if (direction ~= 0) then
            repeat_remaining = repeat_delay
            buffered = direction
            buffer_remaining = buffer_seconds
        end
    end
    started = 0
    arrived = 0
    blocked = 0
    -- Process exact event boundaries so a long update does not skip repeats or overshoot tiles.
    while (1 == 1) do
        if (((target_x ~= tile_x) or (target_y ~= tile_y)) and (progress >= (1 - 1e-09))) then
            tile_x = target_x
            tile_y = target_y
            progress = 0
            arrived = arrived + 1
        end
        if ((held ~= 0) and (repeat_remaining <= 1e-09)) then
            buffered = held
            buffer_remaining = buffer_seconds
            repeat_remaining = repeat_remaining + repeat_interval
        end
        if ((tile_x == target_x) and (tile_y == target_y) and (buffered ~= 0)) then
            nx = tile_x
            ny = tile_y
            if (buffered == 1) then
                ny = ny - 1
            end
            if (buffered == 2) then
                nx = nx + 1
            end
            if (buffered == 3) then
                ny = ny + 1
            end
            if (buffered == 4) then
                nx = nx - 1
            end
            -- Consume each request once, including a blocked request.
            buffered = 0
            buffer_remaining = 0
            passable = 0
            if ((nx >= 0) and (nx < w) and (ny >= 0) and (ny < h)) then
                if (port_get(data, ((17 + (ny * w)) + nx)) == 0) then
                    passable = 1
                end
            end
            if (passable == 0) then
                blocked = 1
            else
                target_x = nx
                target_y = ny
                started = started + 1
                if (step_seconds == 0) then
                    tile_x = target_x
                    tile_y = target_y
                    arrived = arrived + 1
                end
            end
        end
        if (remaining <= 1e-09) then
            break
        end
        advance = remaining
        if (held ~= 0) then
            advance = port_minimum(advance, repeat_remaining)
        end
        if ((tile_x ~= target_x) or (tile_y ~= target_y)) then
            advance = port_minimum(advance, ((1 - progress) * step_seconds))
            progress = progress + (advance / step_seconds)
        end
        remaining = port_maximum(0, (remaining - advance))
        if (held ~= 0) then
            repeat_remaining = port_maximum(0, (repeat_remaining - advance))
        end
        if (buffered ~= 0) then
            buffer_remaining = buffer_remaining - advance
            -- A buffer remains valid at its exact deadline, but expires strictly after it.
            if (buffer_remaining < -(1e-09)) then
                buffered = 0
                buffer_remaining = 0
            else
                buffer_remaining = port_maximum(0, buffer_remaining)
            end
        end
    end
    visual_x = (tile_x + ((target_x - tile_x) * progress))
    visual_y = (tile_y + ((target_y - tile_y) * progress))
    return {tile_x, tile_y, target_x, target_y, progress, buffered, held, repeat_remaining, buffer_remaining, visual_x, visual_y, started, arrived, blocked}
end
return {compute=compute}
